from rich.traceback import install
import sys

install()

def cause_recursion():
    try:
        raise RuntimeError("Original Error")
    except Exception:
        # This might trigger rich traceback, and if that triggers an error, 
        # it might call the excepthook again.
        raise RuntimeError("Second Error") from sys.exc_info()

def trigger():
    try:
        cause_recursion()
    except Exception:
        # Trigger the sys.excepthook
        sys.excepthook(*sys.exc_info())

if __name__ == "__main__":
    trigger()
